mapper.select:
SELECT a.kb_account_id
FROM accounts a
         INNER JOIN kb_accounts k
                    ON k.kb_account_id = a.kb_account_id
WHERE a.account_id = #{accountId}
  AND a.user_id = #{userId}
  AND k.account_type = #{accountType}
    LIMIT 1

SELECT DISTINCT m.kb_account_id
FROM moim_accounts m
         LEFT JOIN `groups` g
                   ON g.moim_account_id = m.moim_account_id
         LEFT JOIN group_users gu
                   ON gu.group_id = g.group_id
                       AND gu.user_id = #{userId}
                       AND gu.group_user_status IN ('ACTIVE', 'PENDING_DEPOSIT')
WHERE m.moim_account_id = #{moimAccountId}
  AND m.account_status = 'ACTIVE'
  AND (
    m.user_id = #{userId}
        OR g.user_id = #{userId}
        OR gu.user_id IS NOT NULL
    )
    LIMIT 1

SELECT at.account_transaction_id, at.kb_account_id, at.group_user_id, at.round_id, r.round_no, at.transaction_type, at.transaction_category, at.amount, at.balance_after, at.idempotency_key, at.description, at.another_account_number, at.another_bank_name, at.another_name, at.created_at FROM account_transactions at LEFT JOIN rounds r ON r.round_id = at.round_id WHERE at.kb_account_id = #{kbAccountId}
AND at.round_id = #{roundId}
ORDER BY at.created_at DESC, at.account_transaction_id DESC LIMIT #{limit} OFFSET #{offset}
